import { Buffer } from "node:buffer";
export default function read({ headers, body, expectedAuthorization, repository }) {
  const h = Object.entries(headers || {}).filter(([k]) => k.toLowerCase() === "authorization"),
    secret = String(expectedAuthorization || ""),
    actual = h.length === 1 ? String(h[0][1]) : "";
  if (
    !/^Basic [A-Za-z0-9+/]+={0,2}$/.test(secret) ||
    !Buffer.from(secret.slice(6), "base64").toString().includes(":")
  )
    throw Error("Configure Basic authorization");
  let diff = secret.length ^ actual.length;
  for (let i = 0; i < Math.max(secret.length, actual.length); i++)
    diff |= (secret.charCodeAt(i) || 0) ^ (actual.charCodeAt(i) || 0);
  if (diff) throw Error("Unauthorized");
  if (
    !/^[A-Za-z0-9_.-]+\/[A-Za-z0-9_.-]+$/.test(repository) ||
    repository.includes("YOUR_") ||
    body.repo !== repository
  )
    throw Error("Unexpected repository");
  const [owner, repo] = repository.split("/"),
    operation = body.operation;
  if (!["getLatestIssues", "getIssueComments", "addIssueComment"].includes(operation))
    throw Error("Unknown operation");
  const issue = Number(body.issueNumber);
  if (operation !== "getLatestIssues" && (!Number.isSafeInteger(issue) || issue < 1))
    throw Error("Invalid issue number");
  const text = String(body.text || "");
  if (operation === "addIssueComment" && (!text.trim() || text.length > 5000))
    throw Error("Comment must contain 1 to 5000 characters");
  return {
    operation,
    owner,
    repo,
    issueNumber: operation === "getLatestIssues" ? 1 : issue,
    text: operation === "addIssueComment" ? text : "-",
    key: "github-comment:" + repository + ":" + issue + ":" + text,
  };
}

