export default async function reserve({ key, acknowledge, resolution }, ctx) {
  const old = await ctx.state.get(key);
  if (old?.status === "done") return { send: false };
  if (old?.status === "pending") {
    if (acknowledge !== key || !["confirmed", "absent"].includes(resolution))
      throw Error("Inspect pending GitHub comment " + key);
    if (resolution === "confirmed") {
      await ctx.state.set(key, { status: "done" });
      return { send: false };
    }
  }
  await ctx.state.set(key, { status: "pending" });
  return { send: true };
}

