export default function f({ issues }) {
  return {
    body: JSON.stringify({
      response: issues.map((x) => ({
        issue_number: x.number,
        title: x.title,
        url: x.url ?? x.html_url,
        reported_by: x.user?.login,
        state: x.state,
        created_at: x.created_at,
        updated_at: x.updated_at,
        body: x.body,
      })),
    }),
  };
}

